window.AUTH=window.AUTH||{};window.AUTH["03-674"]={"d":"03-674","id":"2004/03-674","n":"Jama v. Immigration and Customs Enforcement","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/194941/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/jama-v-immigration-and-naturalization-service-brief-merits","n":69}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep543/usrep543335/usrep543335.pdf","tr":false,"items":[{"t":"case","label":"Ali v. Ashcroft","cite":"346 U.S. 873","y":2003,"court":"9th Cir.","url":"https://supreme.justia.com/cases/federal/us/346/873/","sc":1,"by":{"0":"41"}},{"t":"case","label":"Anderson v. Yungkau","cite":"329 U.S. 482","y":1947,"id":"scdb/1946-034","sc":1,"sum":"More than two years after the deaths of defendants, actions may not be revived and their representatives substituted: and the actions should be dismissedeven though the failure to act within the specified period was the result of \"excusable neglect\" within the meaning of Rule 6 (b). Pp. 484-486. 153 F. 2d 685, affirmed. The District Court denied motions to revive certain actions against certain parties and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Barnhart v. Thomas","cite":"124 S. Ct. 372","y":2003,"id":"2003/02-763","sc":1,"op":3,"sum":"The Court held that the SSA's decision had been a reasonable interpretation of the statute and was therefore entitled to deference under Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc., 467 U.S. 837.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Chi Sheng Liu v. Holton","cite":"297 F.2d 740","y":1961,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/297/740/","op":1,"sum":"Upholding challenged removal on the ground that the country of removal had accepted the alien.","sumSrc":"brief:0","by":{"0":"43, 44"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Great-West Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"0":"27"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"16, 28"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"INS v. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"INS v. Stevic","cite":"467 U.S. 407","y":1984,"id":"1983/82-973","sc":1,"sum":"An alien must establish a clear probability of persecution to avoid deportation under § 243(h).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Lee Wei Fang v. Kennedy","cite":"317 F.2d 180","y":1963,"url":"https://www.courtlistener.com/c/F.2d/317/180/","sum":"Upholding removal of mainland Chinese to Taiwan and Hong Kong, rather than to Communist China.","sumSrc":"brief:0","by":{"0":"43, 44"}},{"t":"case","label":"Lopez v. Davis","cite":"531 U.S. 230","y":2001,"id":"2000/99-7504","sc":1,"sum":"The Court held that the categorically denial of early release to a prisoner who committed felony using firearm is a permissible exercise of the BOP's discretion, even if the prisoner has successfully completed a substance abuse program. \"The Bureau reasonably concluded that an inmate's prior involvement with firearms, in connection with the commission of a felony, suggests his readiness to resort to life-endangering violence and therefore appropriately determines the early release decision,\" wrote Justice Ginsburg for the majority.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Pelich v. INS","cite":"329 F.3d 1057","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/329/1057/","op":1,"sum":"Upholding alien’s ongoing detention during the process of determining his country of citizenship.","sumSrc":"brief:0","by":{"0":"43, 44"}},{"t":"case","label":"Pennsylvania Dep’t of Correction v. Yeskey","cite":"529 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Rogers v. Lu","cite":"262 F.2d 471","y":1958,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/262/471/","op":1,"by":{"0":"44, 45"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"op":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Smith v. United States","cite":"507 U.S. 197","y":1993,"id":"1992/91-1538","sc":1,"sum":"The FTCA does not apply to tortious acts or omissions occurring in Antarctica. The ordinary meaning of \"foreign country\" includes Antarctica, even though it has no recognized government. If this were not so, § 1346(b)-which waives sovereign immunity for certain torts committed \"under circumstances where the United States, if a private person, would be liable... in accordance with the law of the place where the act …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"United States ex rel. Hudak v. Uhl","cite":"20 F. Supp. 928","y":1937,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./20/928/","by":{"0":"41, 42"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"sum":"This action was authorized by the Act of June 21, 1941, 22 U. S. C. § 223, and the proclamations and regulations issued thereunder, notwithstanding the War Brides Act of December 28, 1945, 8 U. S. C. § 232 et seq.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"United States ex rel. Tom Man v. Murff","cite":"264 F.2d 926","y":1959,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/264/926/","op":2,"by":{"0":"44"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"sum":"Section 17 (a) (1) prohibits frauds against brokers as well as investors.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"United States v. Rodgers","cite":"461 U.S. 677","y":1983,"id":"1982/81-1476","sc":1,"sum":"The Court held that section 7403 of the Internal Revenue Code of 1954 does grant the government power to order the sale of a home itself, even if the delinquent taxpayer is not the only one with interest in the property.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1986,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"op":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Zobrest v. Catalina Foothills Sch. Dist.","cite":"509 U.S. 1","y":1993,"id":"1992/92-94","sc":1,"sum":"The Court held that the Establishment Clause did not bar the school district from providing the requested interpreter.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(3)"],"by":{"0":"8"}},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","subs":["(2)"],"stext":{"head":"§251. Transfer of functions","paras":[[0,"In accordance with subchapter XII (relating to transition provisions), there shall be transferred from the Commissioner of Immigration and Naturalization to the Secretary all functions performed under the following programs, and all personnel, assets, and liabilities pertaining to such programs, immediately before such transfer occurs:"],[1,"(1) The Border Patrol program."],[1,"(2) The detention and removal program."],[1,"(3) The intelligence program."],[1,"(4) The investigations program."],[1,"(5) The inspections program."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/6/251?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§251. Transfer of functions","tname":"Domestic Security","by":{"0":"8"}},{"t":"usc","label":"6 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/6/1103","subs":["(g)(1)"],"by":{"0":"8, 28"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1227. Deportable aliens","tname":"Aliens and Nationality","by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(1)","(b)(2)(A)","(b)(2)(C)","(b)(2)(C)(ii)","(b)(2)(C)(iii)","(b)(2)(C)(iv)","(b)(2)(D)","(b)(2)(D)(i)","(b)(2)(D)(ii)","(b)(2)(E)","(b)(2)(E)(i)","(b)(2)(E)(iv)","(b)(2)(E)(vii)","(b)(3)","(b)(3)(A)","(b)(3)(B)(i)","(b)(3)(B)(iv)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[0,"(A) In general"],[2,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(B) Enforcement by attorney general of a State"],[2,"The attorney general of a State, or other authorized State officer, alleging a violation of the detention requirement under subparagraph (A) that harms such State or its residents shall have standing to bring an action against the Secretary of Homeland Security on behalf of such State or the residents of such State in an appropriate district court of the United States to obtain appropriate injunctive relief. The court shall advance on the docket and expedite the disposition of a civil action filed under this subparagraph to the greatest extent practicable. For purposes of this subparagraph, a State or its residents shall be considered to have been harmed if the State or its residents experience harm, including financial harm in excess of $100."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"0":"8, 18, 5, 16, 21, 8, 5, 18, 19, 20, 21, 25, 43, 20, 21, 27, 19, 21, 27, 31, 20, 33, 5, 16, 21, 22, 27, 21, 21, 31, 11, 17, 21, 22, 27, 44, passim, 11, 12, 13, 14, 17, 18, 23, 27, 44, 6, 22, 23, 24, 25, 31, 33, 44, 8, 9, 7, 35, 8, 8"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(g)"],"by":{"0":"11"}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(a)(7)(1994)"],"stext":{"head":"§1253. Penalties related to removal","paras":[[0,"(a) Penalty for failure to depart"],[0,"(1) In general"],[1,"Any alien against whom a final order of removal is outstanding by reason of being a member of any of the classes described in section 1227(a) of this title, who—"],[2,"(A) willfully fails or refuses to depart from the United States within a period of 90 days from the date of the final order of removal under administrative processes, or if judicial review is had, then from the date of the final order of the court,"],[2,"(B) willfully fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure,"],[2,"(C) connives or conspires, or takes any other action, designed to prevent or hamper or with the purpose of preventing or hampering the alien's departure pursuant to such, or"],[2,"(D) willfully fails or refuses to present himself or herself for removal at the time and place required by the Attorney General pursuant to such order,"],[1,"shall be fined under title 18, or imprisoned not more than four years (or 10 years if the alien is a member of any of the classes described in paragraph (1)(E), (2), (3), or (4) of section 1227(a) of this title), or both."],[0,"(2) Exception"],[1,"It is not a violation of paragraph (1) to take any proper steps for the purpose of securing cancellation of or exemption from such order of removal or for the purpose of securing the alien's release from incarceration or custody."],[0,"(3) Suspension"],[1,"The court may for good cause suspend the sentence of an alien under this subsection and order the alien's release under such conditions as the court may prescribe. In determining whether good cause has been shown to justify releasing the alien, the court shall take into account such factors as—"],[2,"(A) the age, health, and period of detention of the alien;"],[2,"(B) the effect of the alien's release upon the national security and public peace or safety;"],[2,"(C) the likelihood of the alien's resuming or following a course of conduct which made or would make the alien deportable;"],[2,"(D) the character of the efforts made by such alien himself and by representatives of the country or countries to which the alien's removal is directed to expedite the alien's departure from the United States;"],[2,"(E) the reason for the inability of the Government of the United States to secure passports, other travel documents, or removal facilities from the country or countries to which the alien has been ordered removed; and"],[2,"(F) the eligibility of the alien for discretionary relief under the immigration laws."],[0,"(b) Willful failure to comply with terms of release under supervision"],[0,"An alien who shall willfully fail to comply with regulations or requirements issued pursuant to section 1231(a)(3) of this title or knowingly give false information in response to an inquiry under such section shall be fined not more than $1,000 or imprisoned for not more than one year, or both."],[0,"(c) Penalties relating to vessels and aircraft"],[0,"(1) Civil penalties"],[0,"(A) Failure to carry out certain orders"],[2,"If the Attorney General is satisfied that a person has violated subsection (d) or (e) of section 1231 of this title, the person shall pay to the Commissioner the sum of $2,000 for each violation."],[0,"(B) Failure to remove alien stowaways"],[2,"If the Attorney General is satisfied that a person has failed to remove an alien stowaway as required under section 1231(d)(2) of this title, the person shall pay to the Commissioner the sum of $5,000 for each alien stowaway not removed."],[0,"(C) No compromise"],[2,"The Attorney General may not compromise the amount of such penalty under this paragraph."],[0,"(2) Clearing vessels and aircraft"],[0,"(A) Clearance before decision on liability"],[2,"A vessel or aircraft may be granted clearance before a decision on liability is made under paragraph (1) only if a bond approved by the Attorney General or an amount sufficient to pay the civil penalty is deposited with the Commissioner."],[0,"(B) Prohibition on clearance while penalty unpaid"],[2,"A vessel or aircraft may not be granted clearance if a civil penalty imposed under paragraph (1) is not paid."],[0,"(d) Discontinuing granting visas to nationals of country denying or delaying accepting alien"],[0,"On being notified by the Attorney General that the government of a foreign country denies or unreasonably delays accepting an alien who is a citizen, subject, national, or resident of that country after the Attorney General asks whether the government will accept the alien under this section, the Secretary of State shall order consular officers in that foreign country to discontinue granting immigrant visas or nonimmigrant visas, or both, to citizens, subjects, nationals, and residents of that country until the Attorney General notifies the Secretary that the country has accepted the alien."],[0,"(e) Enforcement by attorney general of a State"],[0,"The attorney general of a State, or other authorized State officer, alleging a violation of the requirement to discontinue granting visas to citizens, subjects, nationals, and residents as described in subsection (d) that harms such State or its residents shall have standing to bring an action against the Secretary of State on behalf of such State or the residents of such State in an appropriate district court of the United States to obtain appropriate injunctive relief. The court shall advance on the docket and expedite the disposition of a civil action filed under this subsection to the greatest extent practicable. For purposes of this subsection, a State or its residents shall be considered to have been harmed if the State or its residents experience harm, including financial harm in excess of $100."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1253?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1253. Penalties related to removal","tname":"Aliens and Nationality","by":{"0":"24"}},{"t":"usc","label":"8 U.S.C. § 1254a","url":"https://www.law.cornell.edu/uscode/text/8/1254a","subs":["(a)(1)","(b)(1)(A)","(b)(1)(C)","(c)(1)(A)","(c)(2)(B)","(c)(2)(B)(i)"],"stext":{"head":"§1254a. Temporary protected status","paras":[[0,"(a) Granting of status"],[0,"(1) In general"],[1,"In the case of an alien who is a national of a foreign state designated under subsection (b) (or in the case of an alien having no nationality, is a person who last habitually resided in such designated state) and who meets the requirements of subsection (c), the Attorney General, in accordance with this section—"],[2,"(A) may grant the alien temporary protected status in the United States and shall not remove the alien from the United States during the period in which such status is in effect, and"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with an \"employment authorized\" endorsement or other appropriate work permit."],[0,"(2) Duration of work authorization"],[1,"Work authorization provided under this section shall be effective throughout the period the alien is in temporary protected status under this section."],[0,"(3) Notice"],[1,"(A) Upon the granting of temporary protected status under this section, the Attorney General shall provide the alien with information concerning such status under this section."],[1,"(B) If, at the time of initiation of a removal proceeding against an alien, the foreign state (of which the alien is a national) is designated under subsection (b), the Attorney General shall promptly notify the alien of the temporary protected status that may be available under this section."],[1,"(C) If, at the time of designation of a foreign state under subsection (b), an alien (who is a national of such state) is in a removal proceeding under this subchapter, the Attorney General shall promptly notify the alien of the temporary protected status that may be available under this section."],[1,"(D) Notices under this paragraph shall be provided in a form and language that the alien can understand."],[0,"(4) Temporary treatment for eligible aliens"],[1,"(A) In the case of an alien who can establish a prima facie case of eligibility for benefits under paragraph (1), but for the fact that the period of registration under subsection (c)(1)(A)(iv) has not begun, until the alien has had a reasonable opportunity to register during the first 30 days of such period, the Attorney General shall provide for the benefits of paragraph (1)."],[1,"(B) In the case of an alien who establishes a prima facie case of eligibility for benefits under paragraph (1), until a final determination with respect to the alien's eligibility for such benefits under paragraph (1) has been made, the alien shall be provided such benefits."],[0,"(5) Clarification"],[1,"Nothing in this section shall be construed as authorizing the Attorney General to deny temporary protected status to an alien based on the alien's immigration status or to require any alien, as a condition of being granted such status, either to relinquish nonimmigrant or other status the alien may have or to execute any waiver of other rights under this chapter. The granting of temporary protected status under this section shall not be considered to be inconsistent with the granting of nonimmigrant status under this chapter."],[0,"(b) Designations"],[0,"(1) In general"],[1,"The Attorney General, after consultation with appropriate agencies of the Government, may designate any foreign state (or any part of such foreign state) under this subsection only if—"],[2,"(A) the Attorney General finds that there is an ongoing armed conflict within the state and, due to such conflict, requiring the return of aliens who are nationals of that state to that state (or to the part of the state) would pose a serious threat to their personal safety;"],[2,"(B) the Attorney General finds that—"],[3,"(i) there has been an earthquake, flood, drought, epidemic, or other environmental disaster in the state resulting in a substantial, but temporary, disruption of living conditions in the area affected,"],[3,"(ii) the foreign state is unable, temporarily, to handle adequately the return to the state of aliens who are nationals of the state, and"],[3,"(iii) the foreign state officially has requested designation under this subparagraph; or"],[2,"(C) the Attorney General finds that there exist extraordinary and temporary conditions in the foreign state that prevent aliens who are nationals of the state from returning to the state in safety, unless the Attorney General finds that permitting the aliens to remain temporarily in the United States is contrary to the national interest of the United States."],[1,"A designation of a foreign state (or part of such foreign state) under this paragraph shall not become effective unless notice of the designation (including a statement of the findings under this paragraph and the effective date of the designation) is published in the Federal Register. In such notice, the Attorney General shall also state an estimate of the number of nationals of the foreign state designated who are (or within the effective period of the designation are likely to become) eligible for temporary protected status under this section and their immigration status in the United States."],[0,"(2) Effective period of designation for foreign states"],[1,"The designation of a foreign state (or part of such foreign state) under paragraph (1) shall—"],[2,"(A) take effect upon the date of publication of the designation under such paragraph, or such later date as the Attorney General may specify in the notice published under such paragraph, and"],[2,"(B) shall remain in effect until the effective date of the termination of the designation under paragraph (3)(B)."],[1,"For purposes of this section, the initial period of designation of a foreign state (or part thereof) under paragraph (1) is the period, specified by the Attorney General, of not less than 6 months and not more than 18 months."],[0,"(3) Periodic review, terminations, and extensions of designations"],[0,"(A) Periodic review"],[2,"At least 60 days before end of the initial period of designation, and any extended period of designation, of a foreign state (or part thereof) under this section the Attorney General, after consultation with appropriate agencies of the Government, shall review the conditions in the foreign state (or part of such foreign state) for which a designation is in effect under this subsection and shall determine whether the conditions for such designation under this subsection continue to be met. The Attorney General shall provide on a timely basis for the publication of notice of each such determination (including the basis for the determination, and, in the case of an affirmative determination, the period of extension of designation under subparagraph (C)) in the Federal Register."],[0,"(B) Termination of designation"],[2,"If the Attorney General determines under subparagraph (A) that a foreign state (or part of such foreign state) no longer continues to meet the conditions for designation under paragraph (1), the Attorney General shall terminate the designation by publishing notice in the Federal Register of the determination under this subparagraph (including the basis for the determination). Such termination is effective in accordance with subsection (d)(3), but shall not be effective earlier than 60 days after the date the notice is published or, if later, the expiration of the most recent previous extension under subparagraph (C)."],[0,"(C) Extension of designation"],[2,"If the Attorney General does not determine under subparagraph (A) that a foreign state (or part of such foreign state) no longer meets the conditions for designation under paragraph (1), the period of designation of the foreign state is extended for an additional period of 6 months (or, in the discretion of the Attorney General, a period of 12 or 18 months)."],[0,"(4) Information concerning protected status at time of designations"],[1,"At the time of a designation of a foreign state under this subsection, the Attorney General shall make available information respecting the temporary protected status made available to aliens who are nationals of such designated foreign state."],[0,"(5) Review"],[0,"(A) Designations"],[2,"There is no judicial review of any determination of the Attorney General with respect to the designation, or termination or extension of a designation, of a foreign state under this subsection."],[0,"(B) Application to individuals"],[2,"The Attorney General shall establish an administrative procedure for the review of the denial of benefits to aliens under this subsection. Such procedure shall not prevent an alien from asserting protection under this section in removal proceedings if the alien demonstrates that the alien is a national of a state designated under paragraph (1)."],[0,"(c) Aliens eligible for temporary protected status"],[0,"(1) In general"],[0,"(A) Nationals of designated foreign states"],[2,"Subject to paragraph (3), an alien, who is a national of a state designated under subsection (b)(1) (or in the case of an alien having no nationality, is a person who last habitually resided in such designated state), meets the requirements of this paragraph only if—"],[3,"(i) the alien has been continuously physically present in the United States since the effective date of the most recent designation of that state;"],[3,"(ii) the alien has continuously resided in the United States since such date as the Attorney General may designate;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1254a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1254a. Temporary protected status","tname":"Aliens and Nationality","by":{"0":"10, 36, 38, 39, 8, 36, 8, 37, 8, 36, 8, 38, 8, 36, 38, 10"}},{"t":"usc","label":"8 U.S.C. § 1537","url":"https://www.law.cornell.edu/uscode/text/8/1537","subs":["(b)(2)","(b)(2)(A)","(b)(2)(B)"],"by":{"0":"43, 43, 43"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2241. Power to grant writ","tname":"Judiciary and Judicial Procedure","by":{"0":"10"}},{"t":"reg","label":"Pt. 1208.16-1208.18 ................................................................ Miscellaneous: Aliens and Nationality; Homeland Securit, 68 Fed. Reg. 9824","url":"https://www.govinfo.gov/link/fr/68/9824","by":{"0":"34"}},{"t":"reg","label":"8 C.F.R. § 241.15","url":"https://www.ecfr.gov/current/title-8/section-241.15","subs":["(c)"],"by":{"0":"29, 41"}}]};